// V7 shape dividers (PLAN-V7 §4b): a different roofing profile at every section boundary.
// Mechanism: [BANK] Q53 OnScrollPathAnimations / R8 separator. The divider's path is scrubbed with scroll ("ease none")
// from flat to its profile; the start and end paths share one command structure (here: generated by one function, so
// the structure is identical by construction). Adaptation: the viewBox is the divider's own pixel box (kept current by a
// ResizeObserver), so gables, tabs and scallops keep their true proportions at every width instead of stretching.
// The cursor lifts the points nearest the pointer by up to 6px (lerp 0.12); that loop runs only while the pointer is near.
// Fills come from the neighbouring section's active version (--prev-bg / --next-bg, set by main.js on every mount).
// Reduced motion: the finished profile, no scrub, no cursor lift.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

const NS = 'http://www.w3.org/2000/svg';
const f = n => Math.round(n * 10) / 10;
const ease = t => 1 - Math.pow(1 - t, 3);
// every profile: (t 0..1 grown, W, H, lift(x) 0..1 near-cursor weight) -> path d. Hang shapes fill from the top edge down.
const P = {
  // hero -> reviews: the roofline skyline, five gables at different pitches with chimneys, rising out of the next section
  roofline(t, W, H, lift) {
    const pts = [[0, H]], k = ease(t), l = x => 6 * lift(x), types = ['gable', 'hip', 'gable', 'salt', 'gable', 'hip', 'salt'];
    for (let x = 0, i = 0; x < W; i++) {
      const w = 170 + ((i * 97) % 150), ty = types[i % types.length];
      const e = H - H * (0.42 + 0.14 * ((i * 5) % 3) / 2) * k, r = H - H * (0.84 + 0.12 * ((i * 3) % 4) / 3) * k;
      const a = x + 5, b = Math.min(W + 40, x + w - 5), m = (a + b) / 2;
      pts.push([a, H], [a, e - l(a)]);
      if (ty === 'hip') pts.push([a + (b - a) * 0.3, r - l(a + (b - a) * 0.3)], [a + (b - a) * 0.7, r - l(a + (b - a) * 0.7)]);
      else {
        const apex = ty === 'salt' ? a + (b - a) * 0.36 : m;
        pts.push([apex, r - l(apex)]);
        if (i % 3 === 0) { // a chimney up the right slope, flat top
          const sy = X => r + (e - r) * (X - apex) / (b - apex), cx = apex + (b - apex) * 0.38, ch = H * 0.13 * k;
          pts.push([cx, sy(cx) - l(cx)], [cx, sy(cx) - ch - l(cx)], [cx + 14, sy(cx) - ch - l(cx)], [cx + 14, sy(cx + 14) - l(cx)]);
        }
      }
      pts.push([b, e - l(b)], [b, H]);
      x += w;
    }
    pts.push([W + 40, H]);
    return 'M' + pts.map(([x, y]) => `${f(x)},${f(y)}`).join('L') + 'Z';
  },
  // reviews -> work: one course of 3-tab shingles; tabs drop out, lift a little, then lay flat; keyway slots between tabs
  shingles(t, W, H, lift) {
    const band = H * 0.2, tab = H * 0.56, kw = 4, n = Math.max(6, Math.round(W / 120)), w = W / n, k = ease(t);
    let d = `M0,0L${f(W)},0L${f(W)},${f(band)}`;
    for (let i = n - 1; i >= 0; i--) {
      const x1 = (i + 1) * w, x0 = i * w, mid = (x0 + x1) / 2;
      const settle = Math.sin(Math.min(1, t * 1.25) * Math.PI) * 0.14 * ((i % 2) ? 1 : -0.7); // the lift, gone at t = 1
      const y = band + tab * k * (1 + settle) - 6 * lift(mid);
      const r = i === n - 1 ? 0 : kw / 2, L = i ? kw / 2 : 0;
      d += `L${f(x1 - r)},${f(band)}L${f(x1 - r)},${f(y)}L${f(x0 + L)},${f(y)}L${f(x0 + L)},${f(band)}`;
    }
    d += `L0,${f(band)}Z`;
    // the course above: its keyways sit half a tab over, cut into the band as slots
    for (let i = 0; i < n; i++) { const x = (i + 0.5) * w; d += `M${f(x - kw / 2)},${f(band * 0.25)}L${f(x + kw / 2)},${f(band * 0.25)}L${f(x + kw / 2)},${f(band)}L${f(x - kw / 2)},${f(band)}Z`; }
    return d;
  },
  // work -> family: hip-and-ridge cap shingles seen end-on, a row of chevrons whose amplitude grows as you pass
  chevrons(t, W, H, lift) {
    const n = Math.max(8, Math.round(W / 90)), w = W / n, top = H * 0.14, amp = H * 0.62 * ease(t);
    let d = `M0,0L${f(W)},0`;
    for (let i = n; i >= 0; i--) { const x = i * w; d += `L${f(x)},${f(top - 4 * lift(x))}`; if (i) { const xm = x - w / 2; d += `L${f(xm)},${f(top + amp - 6 * lift(xm))}`; } }
    return d + 'Z';
  },
  // family -> how: exposed rafter tails under an eave; tails extend out of the wall line, plumb-cut ends
  rafters(t, W, H, lift) {
    const band = H * 0.16, sp = 64, n = Math.max(6, Math.floor(W / sp)), off = (W - (n - 1) * sp) / 2, tw = 16, len = H * 0.66 * ease(t);
    let d = `M0,0L${f(W)},0L${f(W)},${f(band)}`;
    for (let i = n - 1; i >= 0; i--) {
      const cx = off + i * sp, l = len - 6 * lift(cx);
      d += `L${f(cx + tw / 2)},${f(band)}L${f(cx + tw / 2)},${f(band + l)}L${f(cx - tw / 2)},${f(band + l * 0.82)}L${f(cx - tw / 2)},${f(band)}`;
    }
    return d + `L0,${f(band)}Z`;
  },
  // how -> towns: step flashing, stair-steps that climb left to right in runs of five
  steps(t, W, H, lift) {
    const run = 5, sw = Math.max(26, W / 48), sh = H * 0.13 * ease(t), base = H * 0.12, groups = Math.ceil(W / (sw * run));
    let pts = [[0, 0], [W, 0]], x = W, y;
    const seq = [];
    for (let g = 0; g < groups; g++) for (let k = 0; k < run; k++) { const x0 = (g * run + k) * sw; seq.push([x0, base + (run - k) * sh]); }
    for (let i = seq.length - 1; i >= 0; i--) { const [x0, yy] = seq[i]; const x1 = Math.min(W, x0 + sw); if (x0 >= W) continue; y = yy - 6 * lift((x0 + x1) / 2); pts.push([x1, y], [x0, y]); x = x0; }
    pts.push([0, base]);
    return 'M' + pts.map(([a, b]) => `${f(a)},${f(b)}`).join('L') + 'Z';
  },
  // towns -> call: fish-scale (half-round) shingles, two offset rows; the scallops deepen
  scales(t, W, H, lift) {
    const w = 56, n = Math.ceil(W / w) + 1, band = H * 0.12, dep = H * 0.5 * ease(t);
    let d = `M0,0L${f(W)},0L${f(W)},${f(band)}`;
    for (let i = n - 1; i >= 0; i--) {
      const x1 = Math.min(W, (i + 1) * w), x0 = i * w; if (x0 >= W) continue;
      const mid = (x0 + x1) / 2, dd = dep - 6 * lift(mid);
      d += `C${f(x1)},${f(band + dd * 1.1)} ${f(x0)},${f(band + dd * 1.1)} ${f(x0)},${f(band)}`;
    }
    return d + 'Z';
  },
  // call -> footer: a K-style gutter run with its rolled lip, hangers, and drops that form underneath; it tilts to drain
  gutter(t, W, H, lift) {
    const lip = H * 0.1, body = H * 0.34, tilt = H * 0.06 * ease(t), y = x => lip + body + tilt * (x / W);
    let d = `M0,0L${f(W)},0L${f(W)},${f(y(W))}`;
    const n = Math.max(4, Math.round(W / 260));
    for (let i = n - 1; i >= 0; i--) {
      const cx = (i + 0.5) * W / n + ((i * 37) % 60) - 30, yy = y(cx), drop = H * 0.38 * ease(t) * (0.6 + 0.4 * ((i * 5) % 3) / 2) + 8 * lift(cx);
      d += `L${f(cx + 7)},${f(yy)}C${f(cx + 7)},${f(yy + drop * 0.55)} ${f(cx + 5)},${f(yy + drop)} ${f(cx)},${f(yy + drop)}C${f(cx - 5)},${f(yy + drop)} ${f(cx - 7)},${f(yy + drop * 0.55)} ${f(cx - 7)},${f(yy)}`;
    }
    return d + `L0,${f(y(0))}Z`;
  },
};

// host section id -> [profile, type]. Reviews never hosts one, so Constellation keeps every pixel.
export const DIVIDERS = { hero: ['roofline', 'rise'], work: ['shingles', 'hang'], family: ['chevrons', 'hang'], how: ['rafters', 'hang'], area: ['steps', 'hang'], call: ['scales', 'hang'], foot: ['gutter', 'hang'] };

export function initDividers() {
  const rm = matchMedia('(prefers-reduced-motion: reduce)'), fine = matchMedia('(hover: hover) and (pointer: fine)');
  for (const [id, [name, type]] of Object.entries(DIVIDERS)) {
    const host = document.getElementById(id); if (!host) continue;
    if (type === 'hang') host.dataset.div = name; else host.dataset.divRise = name;
    const svg = document.createElementNS(NS, 'svg'); svg.setAttribute('class', `div div--${type} div--${name}`); svg.setAttribute('fill-rule', 'evenodd');
    svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false'); svg.setAttribute('preserveAspectRatio', 'none');
    // hanging profiles cast a soft shadow line 4px below their edge (shingles read as shingles, not a comb)
    const shade = type === 'hang' ? document.createElementNS(NS, 'path') : null;
    if (shade) { shade.setAttribute('class', 'div-shade'); shade.setAttribute('transform', 'translate(0 4)'); svg.append(shade); }
    const path = document.createElementNS(NS, 'path'); svg.append(path); host.prepend(svg);
    const st = { t: rm.matches ? 1 : 0, W: 1, H: 1, px: -1e4, amp: 0, ampT: 0, raf: 0 };
    const lift = x => (st.amp < 0.01 ? 0 : st.amp * Math.max(0, 1 - Math.abs(x - st.px) / 140) ** 2);
    const render = () => { const d = P[name](st.t, st.W, st.H, lift); path.setAttribute('d', d); if (shade) shade.setAttribute('d', d); };
    const size = () => { const r = svg.getBoundingClientRect(); st.W = Math.max(1, Math.round(r.width)); st.H = Math.max(1, Math.round(r.height)); svg.setAttribute('viewBox', `0 0 ${st.W} ${st.H}`); render(); };
    new ResizeObserver(size).observe(svg); size();
    // Q53: scrub "top bottom" -> the profile is complete well inside reachable scroll (R8 production fix)
    const trig = type === 'rise' ? { trigger: host, start: 'bottom bottom', end: 'bottom 45%' } : { trigger: host, start: 'top bottom', end: 'top 40%' };
    const p = { t: st.t };
    const tw = gsap.to(p, { t: 1, ease: 'none', paused: rm.matches, scrollTrigger: rm.matches ? undefined : { ...trig, scrub: true }, onUpdate: () => { st.t = p.t; render(); } });
    rm.addEventListener('change', () => { if (rm.matches) { tw.scrollTrigger && tw.scrollTrigger.disable(); st.t = 1; render(); } else { tw.scrollTrigger && tw.scrollTrigger.enable(); } });
    // cursor lift: loop only while the pointer is within 160px of the divider
    let drawnPx = NaN, drawnAmp = NaN;
    const tick = () => {
      st.amp += (st.ampT - st.amp) * 0.12;
      if (st.ampT === 0 && st.amp < 0.01) { st.amp = 0; render(); drawnAmp = 0; st.raf = 0; return; }
      // settled under a still pointer: stop until the pointer moves again (no per-frame redraw of an unchanged path)
      if (Math.abs(st.ampT - st.amp) < 0.004 && st.px === drawnPx && Math.abs(st.amp - drawnAmp) < 0.004) { st.raf = 0; return; }
      render(); drawnPx = st.px; drawnAmp = st.amp;
      st.raf = requestAnimationFrame(tick);
    };
    addEventListener('pointermove', e => {
      if (e.pointerType !== 'mouse' || !fine.matches || rm.matches) return;
      const r = svg.getBoundingClientRect(), near = e.clientY > r.top - 160 && e.clientY < r.bottom + 160 && r.bottom > 0 && r.top < innerHeight;
      st.px = e.clientX - r.left; st.ampT = near ? 1 : 0;
      if ((near || st.amp > 0) && !st.raf) st.raf = requestAnimationFrame(tick);
    }, { passive: true });
    document.addEventListener('visibilitychange', () => { if (document.hidden && st.raf) { cancelAnimationFrame(st.raf); st.raf = 0; } });
  }
  ScrollTrigger.refresh();
}
